const headers = $input.item.json.headers || {};
const body = $input.item.json.body || {};

// 1. Verify shared-secret authentication (X-Webhook-Secret)
const providedSecret = headers['x-webhook-secret'] || body.secret || '';
const expectedSecret = $env.CHAT_WEBHOOK_SECRET;

if (!expectedSecret || providedSecret !== expectedSecret) {
  throw new Error("Unauthorized: Invalid or missing X-Webhook-Secret header.");
}

// 2. Validate payload contract: { sessionId, contactEmail, contactName, inquiry, source }
const sessionId = String(body.sessionId || body.session_id || '').trim();
const contactEmail = String(body.contactEmail || body.email || '').trim().toLowerCase();
const contactName = String(body.contactName || body.name || 'Anonymous Visitor').trim();
const rawInquiry = String(body.inquiry || body.query || '').trim();
const source = String(body.source || 'typebot').trim();

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!contactEmail || !emailRegex.test(contactEmail)) {
  throw new Error("Validation Error: Invalid contact email address format.");
}
if (!sessionId) {
  throw new Error("Validation Error: Missing required sessionId parameter.");
}

// Enforce 1000 char limit on inquiry
const inquiry = rawInquiry.substring(0, 1000) || 'General customer inquiry';

// Helper to HTML-escape untrusted user inputs
function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

return {
  json: {
    session_id: sessionId,
    contact_email: contactEmail,
    contact_name: contactName.substring(0, 100),
    inquiry: inquiry,
    summary: inquiry,
    source: source,
    escaped_name: escapeHtml(contactName.substring(0, 100)),
    escaped_email: escapeHtml(contactEmail),
    escaped_inquiry: escapeHtml(inquiry),
    escaped_session_id: escapeHtml(sessionId),
    created_at: new Date().toISOString()
  }
};
